import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    results = []
    T = int(input[idx])
    idx += 1
    for _ in range(T):
        N, M = map(int, input[idx].split())
        idx += 1
        grid = [list(input[idx + i]) for i in range(N)]
        idx += N
        result = min_airstrikes(grid, N, M)
        results.append(result)
    print("\n".join(map(str, results)))

def min_airstrikes(grid, N, M):
    def bfs(start_row, start_col, visited, grid, N, M):
        queue = deque([(start_row, start_col)])
        visited[start_row][start_col] = True
        while queue:
            row, col = queue.popleft()
            if row == N - 1 and col == M - 1:
                return True
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = row + dr, col + dc
                if 0 <= nr < N and 0 <= nc < M and not visited[nr][nc] and grid[nr][nc] == '.':
                    visited[nr][nc] = True
                    queue.append((nr, nc))
        return False

    visited = [[False] * M for _ in range(N)]
    if bfs(0, 0, visited, grid, N, M):
        return 0

    rows_with_walls = set()
    for r in range(N):
        for c in range(M):
            if grid[r][c] == '#':
                rows_with_walls.add(r)

    min_airstrikes_needed = 0
    for row in rows_with_walls:
        for c in range(M):
            grid[row][c] = '.'
        visited = [[False] * M for _ in range(N)]
        if bfs(0, 0, visited, grid, N, M):
            min_airstrikes_needed = 1
            break
        for c in range(M):
            grid[row][c] = '#'

    if min_airstrikes_needed == 0:
        min_airstrikes_needed = len(rows_with_walls)

    return min_airstrikes_needed

if __name__ == "__main__":
    main()
